selector_to_html = {"a[href=\"#advanced-mocking-with-run-code\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">Advanced Mocking with run-code<a class=\"headerlink\" href=\"#advanced-mocking-with-run-code\" title=\"Link to this heading\">#</a></h2><p>For conditional responses, request body inspection, response modification, or delays:</p>", "a[href=\"#simulate-network-failures\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Simulate Network Failures<a class=\"headerlink\" href=\"#simulate-network-failures\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#conditional-response-based-on-request\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Conditional Response Based on Request<a class=\"headerlink\" href=\"#conditional-response-based-on-request\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#request-mocking\"]": "<h1 class=\"tippy-header\" style=\"margin-top: 0;\">Request Mocking<a class=\"headerlink\" href=\"#request-mocking\" title=\"Link to this heading\">#</a></h1><p>Intercept, mock, modify, and block network requests.</p>", "a[href=\"#url-patterns\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">URL Patterns<a class=\"headerlink\" href=\"#url-patterns\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#modify-real-response\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Modify Real Response<a class=\"headerlink\" href=\"#modify-real-response\" title=\"Link to this heading\">#</a></h3>", "a[href=\"#cli-route-commands\"]": "<h2 class=\"tippy-header\" style=\"margin-top: 0;\">CLI Route Commands<a class=\"headerlink\" href=\"#cli-route-commands\" title=\"Link to this heading\">#</a></h2>", "a[href=\"#delayed-response\"]": "<h3 class=\"tippy-header\" style=\"margin-top: 0;\">Delayed Response<a class=\"headerlink\" href=\"#delayed-response\" title=\"Link to this heading\">#</a></h3>"}
skip_classes = ["headerlink", "sd-stretched-link"]

window.onload = function () {
    for (const [select, tip_html] of Object.entries(selector_to_html)) {
        const links = document.querySelectorAll(` ${select}`);
        for (const link of links) {
            if (skip_classes.some(c => link.classList.contains(c))) {
                continue;
            }

            tippy(link, {
                content: tip_html,
                allowHTML: true,
                arrow: true,
                placement: 'auto-start', maxWidth: 500, interactive: false,

            });
        };
    };
    console.log("tippy tips loaded!");
};
